"""Semantic version ordering."""


def _pre_id(ident):
    # Numeric identifiers sort before alphanumeric ones; numerics compare as ints.
    if ident.isdigit():
        return (0, int(ident), "")
    return (1, 0, ident)


def key(version):
    """Sort key: a pre-release (1.0.0-alpha) sorts before its release (1.0.0)."""
    core, _, pre = version.partition("-")
    nums = tuple(int(x) for x in core.split("."))
    if pre:
        # Pre-release: flag 0 sorts before the release flag 1.
        return nums + (0, tuple(_pre_id(p) for p in pre.split(".")))
    return nums + (1, ())

"""Caret ranges like ^1.2.3."""


def satisfies(version, rng):
    """^X.Y.Z allows >= X.Y.Z and < (X+1).0.0 (for X > 0).

    For X == 0 the range is narrowed to the leftmost non-zero component
    (npm semantics): ^0.Y.Z -> <0.(Y+1).0, and ^0.0.Z -> exactly 0.0.Z.
    """
    base = tuple(int(x) for x in rng.lstrip("^").split("."))
    v = tuple(int(x) for x in version.split("."))
    if v < base:
        return False
    major, minor, patch = base
    if major > 0:
        return v[0] == major
    if minor > 0:
        return v[:2] == (0, minor)
    return v[:3] == (0, 0, patch)

